function criarPedido({ id, nome: cliente, quantidade = 1 }) {
  return `Pedido de ${cliente} (cliente ${id}): ${quantidade} unidade(s)`;
}

console.log(criarPedido({ id: 7, nome: 'Marta' }));
// Pedido de Marta (cliente 7): 1 unidade(s)

