const copiaSuperficial = { ...encomenda };
copiaSuperficial.itens.push('borracha');
console.log(encomenda.itens); // ['caneta', 'caderno', 'borracha'] -- afetado!

const copiaProfunda = structuredClone(encomenda);
copiaProfunda.itens.push('lápis');
console.log(encomenda.itens); // ['caneta', 'caderno', 'borracha'] -- inalterado
console.log(copiaProfunda.itens); // ['caneta', 'caderno', 'borracha', 'lápis']

