function atualizarConfig(configAtual, novasOpcoes) {
  return { ...configAtual, ...novasOpcoes };
}

function extrairEssenciais(config) {
  const { tema, idioma, ...resto } = config;
  return [tema, idioma, resto];
}

const configOriginal = { tema: 'claro', idioma: 'pt-PT', fonte: 14, animacoes: true };

const configNova = atualizarConfig(configOriginal, { tema: 'escuro', fonte: 16 });
console.log(configNova);
// { tema: 'escuro', idioma: 'pt-PT', fonte: 16, animacoes: true }
console.log(configOriginal);
// { tema: 'claro', idioma: 'pt-PT', fonte: 14, animacoes: true } (inalterado)

console.log(extrairEssenciais(configOriginal));
// ['claro', 'pt-PT', { fonte: 14, animacoes: true }]

// O spread {...carrinho} cria um objeto novo, mas a propriedade "itens"
// continua a apontar para o MESMO array (e os mesmos objetos dentro dele)
// que existia em "carrinho". É uma cópia superficial: só o primeiro
// nível é duplicado, por isso alterar itens[0] através do backup
// altera a mesma estrutura partilhada e reflete-se em "carrinho".

const carrinho = { cliente: 'João', itens: [{ nome: 'Livro', quantidade: 1 }] };

const carrinhoBackup = structuredClone(carrinho);
carrinhoBackup.itens[0].quantidade = 5;

console.log(carrinho.itens[0].quantidade); // 1 (inalterado)
console.log(carrinhoBackup.itens[0].quantidade); // 5
